/// The copy language a chosen language falls back to for the full app text.
String copyLangFor(String code) {
  if (code == 'pa') return 'pa';
  if (const ['hi', 'mai', 'doi', 'kok', 'sa', 'brx', 'mr', 'ne']
      .contains(code)) {
    return 'hi';
  }
  return 'en';
}

