/// Right-to-left scripts among the supported languages.
bool isRtl(String code) => const ['ur', 'ks', 'sd'].contains(code);

/// Resolve the copy table for a chosen language: the nearest complete language,
/// overlaid with whatever this language itself provides.
Str stringsFor(String langCode) {
  final tables = <String, Map<String, String>>{'en': _en, 'hi': _hi, 'pa': _pa, 'ml': _ml, 'as': _as, 'kn': _kn, 'or': _or, 'ks': _ks, 'sd': _sd, 'bn': _bn, 'ta': _ta, 'mr': _mr, 'gu': _gu, 'te': _te, 'ur': _ur, 'sat': _sat, 'sa': _sa, 'mni': _mni, 'ne': _ne, 'kok': _kok, 'doi': _doi, 'mai': _mai, 'brx': _brx};
  // A fully-translated language (everything in [tables]) uses its own table
  // as the base. Only a language with no table of its own at all (Maithili,
  // Dogri, Konkani, Sanskrit, Bodo, Nepali, Urdu — onboarding-only copy)
  // falls back to its nearest complete relative via copyLangFor. Using
  // copyLangFor unconditionally here was the bug that made every fully
  // translated language past the splash screen silently read in English.
  final base = tables[langCode] ?? tables[copyLangFor(langCode)]!;
  String pick(Map<String, String> table, String key) =>
      table[langCode] ?? base[key] ?? key;
  // English is the only table guaranteed to have every key; any string not
  // yet translated for [base] (Punjabi in particular has real gaps) should
  // read in English rather than surface as a raw untranslated key like
  // "shortlisted" — so English goes down first and the language's own
  // translations are layered on top of it, not the other way around.
  final merged = Map<String, String>.from(_en)
    ..addAll(base)
    ..addAll(kRolePacks[langCode] ?? const {})
    ..addAll({
      'appName': pick(kAppName, 'appName'),
      'tagline': pick(kTagline, 'tagline'),
      'getStarted': pick(kGetStarted, 'getStarted'),
      'continueBtn': pick(kContinue, 'continueBtn'),
      'listen': pick(kListen, 'listen'),
      'listening': pick(kListening, 'listening'),
      'language': pick(kLanguageWord, 'language'),
      'chooseLanguage': pick(kChooseLanguage, 'chooseLanguage'),
      'changeWord': pick(kChangeWord, 'changeWord'),
    });
  return Str(merged);
}
